{"code": "export async function main(input: {}): Promise<unknown> {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });

  // Unresolved issues with at least 0 events (all of them, but verified per issue).
  const candidates: { shortId: string; culprit: string; events: number }[] = [];
  for (const i of issues) {
    if (i.status !== "unresolved") continue;
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    if (events.length >= 0) candidates.push({ shortId: i.shortId, culprit: i.culprit, events: events.length });
  }

  // One entry per distinct culprit, in first-seen order.
  const culprits: string[] = [];
  for (const c of candidates) if (!culprits.includes(c.culprit)) culprits.push(c.culprit);

  const created: { culprit: string; title: string; result: unknown }[] = [];
  const skipped: { culprit: string; existing: string[] }[] = [];

  for (const culprit of culprits) {
    const { issues: found } = await sdk.linear.searchIssues({ query: culprit });
    const mentioning = found.filter(l => l.title.includes(culprit) || l.description.includes(culprit));
    if (mentioning.length > 0) {
      skipped.push({ culprit, existing: mentioning.map(l => l.identifier) });
      continue;
    }
    const title = `[Sentry] ${culprit}`;
    const res = await sdk.linear.createIssue({ title, description: culprit });
    created.push({ culprit, title, result: res });
  }

  return {
    unresolvedIssues: candidates.length,
    distinctCulprits: culprits.length,
    created,
    skipped,
  };
}"}

